// Placeholder for the real backend. Steps 4-6 implement the commands in Rust
// and replace each method with an `invoke` call (generated by tauri-specta)
// plus the mapping from the typed Rust error to the method's compat shape.

import { PORTED_METHODS, type MaatwerkApi } from './api';

function notYet(method: string): never {
  throw new Error(`window.maatwerk.${method} is nog niet beschikbaar in deze versie (Step 6).`);
}

export function createTauriApi(): MaatwerkApi {
  const api: Record<string, unknown> = {};
  for (const method of PORTED_METHODS) {
    api[method] = async () => notYet(method);
  }
  api.onDataChanged = () => () => {};
  api.onAssignmentProgress = () => () => {};
  api.pdfUrl = (pdfPath: string) => notYet(`pdfUrl(${pdfPath})`);
  return api as unknown as MaatwerkApi;
}
